function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 2000 : pick(3, 10);
  const shape = pick(0, 3);
  let arr;
  if (shape === 0) arr = Array.from({ length: n }, () => pick(0, 100));
  else if (shape === 1) arr = Array.from({ length: n }, () => pick(0, 4));
  else if (shape === 2) { const v = pick(0, 100); arr = Array.from({ length: n }, () => v); }
  else { const base = pick(0, 95); arr = Array.from({ length: n }, () => base + pick(0, 5)); }
  let target;
  if (rand() < 0.75) {
    const a = pick(0, n - 1);
    let b = pick(0, n - 2); if (b >= a) b++;
    let c = pick(0, n - 1);
    while (c === a || c === b) c = pick(0, n - 1);
    target = arr[a] + arr[b] + arr[c];
  } else {
    target = pick(0, 300);
  }
  return [arr, target];
}
